+using Microsoft.AspNetCore.Components;
+
+namespace sv_50bbe3449f6b4ede9b1aa321b87970f3;
+
+/// <summary>
+/// Scoped service that holds theme state for a single circuit/user.
+/// Components inject this to read or change the theme, then call
+/// NotifyChanged() which updates the CascadingValueSource so all
+/// [CascadingParameter] subscribers re-render automatically.
+/// </summary>
+public class ThemeService
+{
+    private readonly CascadingValueSource<ThemeInfo> _source;
+
+    public ThemeService(CascadingValueSource<ThemeInfo> source)
+    {
+        _source = source;
+    }
+
+    public ThemeInfo Current { get; private set; } = new();
+
+    public event Action? OnChange;
+
+    public async Task SetThemeAsync(Theme theme)
+    {
+        Current.Theme = theme;
+        await NotifyAsync();
+    }
+
+    public async Task SetAccentColorAsync(string color)
+    {
+        Current.AccentColor = color;
+        await NotifyAsync();
+    }
+
+    public async Task UpdateAsync(Theme theme, string accentColor)
+    {
+        Current.Theme = theme;
+        Current.AccentColor = accentColor;
+        await NotifyAsync();
+    }
+
+    private async Task NotifyAsync()
+    {
+        // Push the updated value to all [CascadingParameter] subscribers
+        await _source.NotifyChangedAsync(Current);
+        // Also fire the event for components subscribing via DI
+        OnChange?.Invoke();
+    }
