</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string ThemeLabel => Theme?.Theme switch
    {
        Theme.Dark   => "🌙 Dark",
        Theme.System => "💻 System",
        _            => "☀️ Light"
    };

    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject ThemeService ThemeSvc

<button class="btn btn-sm btn-outline-secondary" @onclick="ToggleTheme"
        title="Toggle theme">
    @(ThemeSvc.Current.Theme switch
    {
        Theme.Dark   => "🌙",
        Theme.System => "💻",
        _            => "☀️"
    })
</button>

@code {
    private static readonly Theme[] Cycle = [Theme.Light, Theme.Dark, Theme.System];

    private async Task ToggleTheme()
    {
        var next = Cycle[(Array.IndexOf(Cycle, ThemeSvc.Current.Theme) + 1) % Cycle.Length];
        await ThemeSvc.SetThemeAsync(next);
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h2>User Preferences</h2>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <div class="mb-3">
            <label class="form-label fw-bold">Theme</label>
            <select class="form-select" value="@selectedTheme" @onchange="OnThemeSelected">
                <option value="Light">☀️ Light</option>
                <option value="Dark">🌙 Dark</option>
                <option value="System">💻 System</option>
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label fw-bold">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   value="@accentColor" @onchange="OnColorChanged" />
        </div>

        <button class="btn btn-primary" @onclick="Save"
                style="background-color: @accentColor; border-color: @accentColor;">
            Save Preferences
        </button>
    </div>
</div>

<div class="mt-3">
    <strong>Current:</strong> @ThemeLabel, accent
    <span class="badge" style="background-color: @accentColor;">@accentColor</span>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string selectedTheme = nameof(Theme.Light);
    private string accentColor = "#0d6efd";

    private string ThemeLabel => Theme?.Theme.ToString() ?? "Light";

    protected override void OnInitialized()
    {
        selectedTheme = ThemeSvc.Current.Theme.ToString();
        accentColor = ThemeSvc.Current.AccentColor;
        ThemeSvc.OnChange += OnExternalChange;
    }

    private void OnExternalChange() => InvokeAsync(StateHasChanged);

    private void OnThemeSelected(ChangeEventArgs e)
    {
        selectedTheme = e.Value?.ToString() ?? nameof(Theme.Light);
    }

    private void OnColorChanged(ChangeEventArgs e)
    {
        accentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private async Task Save()
    {
        var theme = Enum.Parse<Theme>(selectedTheme);
        await ThemeSvc.UpdateAsync(theme, accentColor);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= OnExternalChange;
    }
}

